namespace scratchbird::engine::sblr{namespace{template<class A>bool nz(const A&a){return std::any_of(a.begin(),a.end(),[](auto b){return b;});}void p16(auto&o,std::uint16_t v){o.push_back(v);o.push_back(v>>8);}void p32(auto&o,std::uint32_t v){for(int i=0;i<4;++i)o.push_back(v>>(8*i));}void p64(auto&o,std::uint64_t v){for(int i=0;i<8;++i)o.push_back(v>>(8*i));}std::uint32_t u32(const std::uint8_t*p){std::uint32_t v=0;for(int i=3;i>=0;--i)v=v*256+p[i];return v;}std::uint64_t u64(const std::uint8_t*p){std::uint64_t v=0;for(int i=7;i>=0;--i)v=v*256+p[i];return v;}void put(auto&o,const auto&a){o.insert(o.end(),a.begin(),a.end());}void get(const std::uint8_t*p,auto&a){std::copy(p,p+a.size(),a.begin());}bool head(const std::uint8_t*b,size_t n,const char*m,size_t z){return n==z&&std::equal(m,m+4,b)&&b[4]==1&&!b[5]&&b[6]==(z&255)&&b[7]==(z>>8)&&u32(b+8)==z&&!u32(b+12);}auto hash(const char*d,const std::vector<std::uint8_t>&b){std::vector<std::uint8_t>m(d,d+std::char_traits<char>::length(d));m.insert(m.end(),b.begin(),b.end());return scratchbird::core::hash::ComputeSha256Digest(m).digest;}}
std::vector<std::uint8_t>EncodeSblrCursorFetchOperandV1(const SblrCursorFetchOperandV1&v){if(!nz(v.cursor)||!v.cursor_generation||!nz(v.plan)||!v.plan_generation||!nz(v.row_shape)||!v.row_shape_generation||!nz(v.session)||!v.position_generation||!v.maximum_rows||v.maximum_rows>65535||!nz(v.cursor_evidence)||!v.availability_generation)return{};std::vector<std::uint8_t>o{'C','F','O','P'};p16(o,1);p16(o,176);p32(o,176);p32(o,0);put(o,v.cursor);p64(o,v.cursor_generation);put(o,v.plan);p64(o,v.plan_generation);put(o,v.row_shape);p64(o,v.row_shape_generation);put(o,v.transaction);put(o,v.session);p64(o,v.position_generation);p32(o,v.maximum_rows);p32(o,0);put(o,v.cursor_evidence);p64(o,v.availability_generation);return o;}
bool DecodeSblrCursorFetchOperandV1(const std::uint8_t*b,size_t n,SblrCursorFetchOperandV1*out,std::string*d){if(!out||!head(b,n,"CFOP",176)){if(d)*d="CFOP invalid";return false;}SblrCursorFetchOperandV1 v;get(b+16,v.cursor);v.cursor_generation=u64(b+32);get(b+40,v.plan);v.plan_generation=u64(b+56);get(b+64,v.row_shape);v.row_shape_generation=u64(b+80);get(b+88,v.transaction);get(b+104,v.session);v.position_generation=u64(b+120);v.maximum_rows=u32(b+128);get(b+136,v.cursor_evidence);v.availability_generation=u64(b+168);if(u32(b+132)||EncodeSblrCursorFetchOperandV1(v).empty())return false;*out=v;return true;}
std::vector<std::uint8_t>EncodeSblrCursorFetchResultV1(const SblrCursorFetchResultV1&v){if(!nz(v.cursor)||!v.cursor_generation||!v.prior_position_generation||v.resulting_position_generation!=v.prior_position_generation+1||v.eof>1||!nz(v.row_batch_sha)||!nz(v.refreshed_cursor_evidence)||!v.availability_generation)return{};std::vector<std::uint8_t>o{'C','F','R','S'};p16(o,1);p16(o,168);p32(o,168);p32(o,0);put(o,v.cursor);p64(o,v.cursor_generation);p64(o,v.prior_position_generation);p64(o,v.resulting_position_generation);p32(o,v.returned_rows);o.push_back(v.eof);o.insert(o.end(),3,0);put(o,v.row_batch_sha);put(o,v.refreshed_cursor_evidence);p64(o,v.availability_generation);auto e=hash("ScratchBird.SblrCursorFetchResult.V1",o);if(nz(v.result_evidence)&&v.result_evidence!=e)return{};put(o,e);return o;}
bool DecodeSblrCursorFetchResultV1(const std::uint8_t*b,size_t n,SblrCursorFetchResultV1*out,std::string*d){if(!out||!head(b,n,"CFRS",168)){if(d)*d="CFRS invalid";return false;}SblrCursorFetchResultV1 v;get(b+16,v.cursor);v.cursor_generation=u64(b+32);v.prior_position_generation=u64(b+40);v.resulting_position_generation=u64(b+48);v.returned_rows=u32(b+56);v.eof=b[60];get(b+64,v.row_batch_sha);get(b+96,v.refreshed_cursor_evidence);v.availability_generation=u64(b+128);get(b+136,v.result_evidence);if(std::any_of(b+61,b+64,[](auto x){return x;})||EncodeSblrCursorFetchResultV1(v).empty())return false;*out=v;return true;}}
